begin;
-- Object-scoped representation, not organization membership or contract access.
create table private.partner_delegation_settings(site_id uuid primary key,organization_id uuid not null,enabled boolean not null default false,foreign key(organization_id,site_id)references public.publication_sites(organization_id,id));
create table private.partner_delegations(id uuid primary key default gen_random_uuid(),organization_id uuid not null,site_id uuid not null,partner_id uuid not null,access_id uuid not null references private.platform_access(id),person_id uuid not null,user_id uuid not null references public.profiles(id),proof_document_id uuid not null references public.document_registry(id),proof_hash text not null,valid_until timestamptz not null,revoked_at timestamptz,created_at timestamptz not null default clock_timestamp(),created_by uuid not null references public.profiles(id),foreign key(organization_id,site_id)references public.publication_sites(organization_id,id),foreign key(partner_id)references public.partners(id),foreign key(person_id)references public.community_people(id),unique(organization_id,id));
create unique index partner_delegation_active_binding on private.partner_delegations(site_id,partner_id,access_id)where revoked_at is null;
create table private.partner_profile_proposals(id uuid primary key default gen_random_uuid(),organization_id uuid not null,delegation_id uuid not null,revision integer not null check(revision>0),payload jsonb not null,payload_sha256 text not null,source_hash text not null,status text not null default 'draft'check(status in('draft','submitted','changes_requested','prepared','withdrawn')),own_message text not null default ''check(length(own_message)<=2000),created_at timestamptz not null default clock_timestamp(),created_by uuid not null references public.profiles(id),prepared_revision_id uuid references private.partner_publication_revisions(id),foreign key(organization_id,delegation_id)references private.partner_delegations(organization_id,id),unique(delegation_id,revision),unique(organization_id,id));
alter table private.partner_publication_revisions add column delegated_proposal_id uuid references private.partner_profile_proposals(id);
do $$declare t text;begin foreach t in array array['partner_delegation_settings','partner_delegations','partner_profile_proposals']loop execute format('alter table private.%I enable row level security',t);execute format('revoke all on private.%I from public,anon,authenticated,service_role',t);end loop;end$$;
create function private.f4_delegation_payload(p jsonb)returns boolean language sql immutable set search_path=''as $$
 select coalesce(jsonb_typeof(p)='object'and pg_column_size(p)<=16000 and p?&array['name','description','website_url']and not exists(select 1 from jsonb_object_keys(p)k where k not in('name','description','website_url'))and jsonb_typeof(p->'name')='string'and length(btrim(p->>'name'))between 2 and 180 and jsonb_typeof(p->'description')='string'and length(btrim(p->>'description'))between 1 and 4000 and(jsonb_typeof(p->'website_url')='string'or p->'website_url'='null'::jsonb)and private.f4_partner_url(p->>'website_url'),false)
$$;
create function private.f4_delegation_source(o uuid,p uuid)returns text language sql stable security definer set search_path=''as $$select encode(sha256(convert_to(jsonb_build_object('name',x.name,'website_url',nullif(btrim(x.website),''),'status',x.status,'deleted_at',x.deleted_at)::text,'UTF8')),'hex')from public.partners x where x.organization_id=o and x.id=p and x.status='active'and x.deleted_at is null$$;
create function private.f4_delegation_valid(i uuid)returns boolean language sql stable security definer set search_path=''as $$
 select exists(select 1 from private.partner_delegations d join public.publication_sites s on s.id=d.site_id join private.partner_delegation_settings cfg on cfg.site_id=s.id join private.platform_access a on a.id=d.access_id join public.partners p on p.id=d.partner_id where d.id=i and cfg.enabled and s.active and d.revoked_at is null and d.valid_until>clock_timestamp()and private.f4_access_valid(a.id)and a.organization_id=d.organization_id and p.organization_id=d.organization_id and a.site_id=s.id and a.person_id=d.person_id and a.user_id=d.user_id and d.proof_hash=private.f4_partner_document(d.organization_id,d.proof_document_id)and p.status='active'and p.deleted_at is null)
$$;
create function private.f4_delegation_own(i uuid)returns boolean language sql stable security definer set search_path=''as $$select private.f4_identity()and exists(select 1 from private.partner_delegations d where d.id=i and d.user_id=auth.uid()and private.f4_delegation_valid(d.id))$$;
create function private.f4_delegation_current(p private.partner_profile_proposals)returns boolean language sql stable security definer set search_path=''as $$select private.f4_delegation_payload(p.payload)and exists(select 1 from private.partner_delegations d where d.id=p.delegation_id and private.f4_delegation_valid(d.id)and p.source_hash=private.f4_delegation_source(d.organization_id,d.partner_id))$$;
create function public.f4_delegation_workflow(p_site_id uuid,p_operation text,p_data jsonb,p_request_id uuid)returns jsonb language plpgsql volatile security definer set search_path=''as $$
declare s public.publication_sites;d private.partner_delegations;p private.partner_profile_proposals;a private.platform_access;prior private.f4_receipts;op text:=p_operation;j jsonb:=p_data;allowed text[];ident uuid;v integer;h text;result jsonb;pub jsonb;begin
 perform private.f4_read_gate();select * into s from public.publication_sites where id=p_site_id;
 if s.id is null or p_request_id is null or j is null or jsonb_typeof(j)<>'object'or pg_column_size(j)>20000 then raise exception'delegation_not_available'using errcode='42501';end if;
 allowed:=case op when'site.configure'then array['enabled','reason']when'delegation.assign'then array['partner_id','person_id','proof_document_id','valid_until']when'delegation.revoke'then array['id','reason']when'delegation.end'then array['id','reason']when'proposal.save'then array['delegation_id','expected_revision','payload']when'proposal.submit'then array['id','expected_hash']when'proposal.withdraw'then array['id','expected_hash']when'proposal.respond'then array['id','expected_hash','message']when'proposal.prepare'then array['id','expected_hash','expected_partner_revision','slug','locale','role_ids','proof_document_id']else null end;
 if allowed is null or not(j?&allowed)or exists(select 1 from jsonb_object_keys(j)k where not(k=any(allowed)))then raise exception'delegation_invalid_input';end if;
 if op in('site.configure','delegation.assign','delegation.revoke')then
  if not private.f2_account(s.organization_id)or not private.f1_chair(s.organization_id)then raise exception'delegation_not_authorized'using errcode='42501';end if;
 elsif op in('proposal.respond','proposal.prepare')then
  if not private.f2_account(s.organization_id)or not private.f1_role(s.organization_id,'publication_editor')or not private.f1_role(s.organization_id,'partner_editor')then raise exception'delegation_not_authorized'using errcode='42501';end if;
 end if;
 if op like'proposal.%'and op<>'proposal.save'then select * into p from private.partner_profile_proposals where id=(j->>'id')::uuid and organization_id=s.organization_id for update;select * into d from private.partner_delegations where id=p.delegation_id and site_id=s.id;
 elsif op='proposal.save'then select * into d from private.partner_delegations where id=(j->>'delegation_id')::uuid and site_id=s.id for update;
 elsif op in('delegation.end','delegation.revoke')then select * into d from private.partner_delegations where id=(j->>'id')::uuid and site_id=s.id for update;end if;
 if op in('proposal.save','proposal.submit','proposal.withdraw','delegation.end')then if d.id is null or not private.f4_delegation_own(d.id)then raise exception'delegation_not_authorized'using errcode='42501';end if;
 elsif op in('proposal.respond','proposal.prepare')then if p.id is null or not private.f4_delegation_valid(d.id)or not private.f1_document_visible(s.organization_id,d.proof_document_id)then raise exception'delegation_not_authorized'using errcode='42501';end if;
 elsif op='delegation.revoke'and d.id is null then raise exception'delegation_not_authorized'using errcode='42501';end if;
 select * into prior from private.f4_receipts where site_id=s.id and actor=auth.uid()and request_id=p_request_id;if found then if prior.operation<>'delegation.'||op or prior.input<>j then raise exception'delegation_request_conflict'using errcode='40001';end if;return prior.result;end if;perform private.f4_limit(s.id,'delegation_write',30);
 if op='site.configure'then
  if jsonb_typeof(j->'enabled')is distinct from'boolean'or jsonb_typeof(j->'reason')is distinct from'string'or length(btrim(j->>'reason'))not between 2 and 2000 then raise exception'delegation_invalid_input';end if;insert into private.partner_delegation_settings values(s.id,s.organization_id,(j->>'enabled')::boolean)on conflict(site_id)do update set enabled=excluded.enabled;ident:=s.id;
 elsif op='delegation.assign'then
  select x.* into a from private.platform_access x where x.site_id=s.id and x.person_id=(j->>'person_id')::uuid and private.f4_access_valid(x.id);
  if a.id is null or(select count(*)from private.platform_access x where x.site_id=s.id and x.person_id=(j->>'person_id')::uuid and private.f4_access_valid(x.id))<>1 or not exists(select 1 from public.partners where id=(j->>'partner_id')::uuid and organization_id=s.organization_id and status='active'and deleted_at is null)or not private.f1_document_visible(s.organization_id,(j->>'proof_document_id')::uuid)or private.f4_partner_document(s.organization_id,(j->>'proof_document_id')::uuid)is null or j->>'valid_until'is null or(j->>'valid_until')::timestamptz<=clock_timestamp()or(j->>'valid_until')::timestamptz>least(a.valid_until,clock_timestamp()+interval'7 days')then raise exception'delegation_invalid_input';end if;
  if(select count(*)from private.partner_delegations where site_id=s.id)>=500 or(select count(*)from private.partner_delegations where site_id=s.id and access_id=a.id and revoked_at is null and valid_until>clock_timestamp())>=20 then raise exception'delegation_capacity';end if;
  insert into private.partner_delegations(organization_id,site_id,partner_id,access_id,person_id,user_id,proof_document_id,proof_hash,valid_until,created_by)values(s.organization_id,s.id,(j->>'partner_id')::uuid,a.id,a.person_id,a.user_id,(j->>'proof_document_id')::uuid,private.f4_partner_document(s.organization_id,(j->>'proof_document_id')::uuid),(j->>'valid_until')::timestamptz,auth.uid())returning id into ident;
 elsif op in('delegation.revoke','delegation.end')then
  if jsonb_typeof(j->'reason')is distinct from'string'or length(btrim(j->>'reason'))not between 2 and 2000 then raise exception'delegation_invalid_input';end if;update private.partner_delegations set revoked_at=coalesce(revoked_at,clock_timestamp())where id=d.id;ident:=d.id;
 elsif op='proposal.save'then
  if jsonb_typeof(j->'expected_revision')is distinct from'number'or coalesce(j->>'expected_revision','')!~'^(0|[1-9][0-9]*)$'or not private.f4_delegation_payload(j->'payload')then raise exception'delegation_invalid_input';end if;
  select coalesce(max(revision),0)into v from private.partner_profile_proposals where delegation_id=d.id;if v<>(j->>'expected_revision')::integer then raise exception'delegation_version_conflict'using errcode='40001';end if;
  if v>=100 or(select count(*)from private.partner_profile_proposals where organization_id=s.organization_id)>=2000 then raise exception'delegation_capacity';end if;
  h:=private.f4_delegation_source(s.organization_id,d.partner_id);if h is null then raise exception'delegation_source_invalid';end if;
  insert into private.partner_profile_proposals(organization_id,delegation_id,revision,payload,payload_sha256,source_hash,created_by)values(s.organization_id,d.id,v+1,j->'payload',encode(sha256(convert_to((j->'payload')::text,'UTF8')),'hex'),h,auth.uid())returning id into ident;
 else
  if p.id is null or j->>'expected_hash'is distinct from p.payload_sha256 then raise exception'delegation_version_conflict'using errcode='40001';end if;ident:=p.id;
  if op='proposal.submit'then
   if p.status<>'draft'or not coalesce(private.f4_delegation_current(p),false)then raise exception'delegation_source_or_version_invalid';end if;update private.partner_profile_proposals set status='submitted'where id=p.id;
  elsif op='proposal.withdraw'then
   if p.status not in('draft','submitted','changes_requested','prepared')then raise exception'delegation_version_conflict'using errcode='40001';end if;update private.partner_profile_proposals set status='withdrawn'where id=p.id;
  elsif op='proposal.respond'then
   if p.status<>'submitted'or jsonb_typeof(j->'message')is distinct from'string'or length(btrim(j->>'message'))not between 2 and 2000 then raise exception'delegation_invalid_input';end if;update private.partner_profile_proposals set status='changes_requested',own_message=j->>'message'where id=p.id;
  else
   if p.status<>'submitted'or not coalesce(private.f4_delegation_current(p),false)then raise exception'delegation_source_or_version_invalid';end if;
   if not exists(select 1 from public.partners x where x.id=d.partner_id and x.name=p.payload->>'name'and nullif(btrim(x.website),'')is not distinct from p.payload->>'website_url')then raise exception'delegation_source_update_required';end if;
   if jsonb_typeof(j->'expected_partner_revision')is distinct from'number'or coalesce(j->>'expected_partner_revision','')!~'^(0|[1-9][0-9]*)$'or jsonb_typeof(j->'role_ids')is distinct from'array'then raise exception'delegation_invalid_input';end if;
   pub:=jsonb_build_object('partner_id',d.partner_id,'expected_revision',(j->>'expected_partner_revision')::integer,'role_ids',j->'role_ids','proof_document_id',j->>'proof_document_id','payload',jsonb_build_object('slug',j->>'slug','locale',j->>'locale','name',p.payload->>'name','description',p.payload->>'description','website_url',p.payload->'website_url','logo',null,'roles',(select jsonb_agg(role order by role)from public.partner_roles where id in(select value::uuid from jsonb_array_elements_text(j->'role_ids')))));
   result:=public.f4_partner_workflow(s.id,'partner.draft',pub,p_request_id);update private.partner_profile_proposals set status='prepared',prepared_revision_id=(result->>'id')::uuid where id=p.id;
   update private.partner_publication_revisions set delegated_proposal_id=p.id where id=(result->>'id')::uuid;
   -- The nested workflow used this same request under its namespace. Keep the outer receipt canonical.
   delete from private.f4_receipts where site_id=s.id and actor=auth.uid()and request_id=p_request_id;
  end if;
 end if;result:=jsonb_build_object('id',ident);perform private.f1_audit(s.organization_id,ident,'f4.delegation.'||op);insert into private.f4_receipts values(s.id,auth.uid(),p_request_id,'delegation.'||op,j,result);return result;
end$$;
create function public.f4_delegation_me(p_site_id uuid,p_id uuid default null)returns jsonb language plpgsql volatile security definer set search_path=''as $$declare aid uuid;ds jsonb;ps jsonb;begin
 perform private.f4_read_gate();aid:=private.f4_intake_own(p_site_id);if aid is null or not exists(select 1 from private.partner_delegation_settings where site_id=p_site_id and enabled)then raise exception'delegation_not_authorized'using errcode='42501';end if;perform private.f4_limit(p_site_id,'delegation_own_read',90);
 if p_id is not null and not exists(select 1 from private.partner_delegations where id=p_id and site_id=p_site_id and private.f4_delegation_own(id))then raise exception'delegation_not_authorized'using errcode='42501';end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',d.id,'partner',jsonb_build_object('name',x.name,'website_url',case when private.f4_partner_url(nullif(btrim(x.website),''))then nullif(btrim(x.website),'')else null end),'valid_until',d.valid_until,'revision',(select coalesce(max(revision),0)from private.partner_profile_proposals where delegation_id=d.id))order by d.created_at desc,d.id desc),'[]')into ds from private.partner_delegations d join public.partners x on x.id=d.partner_id where d.site_id=p_site_id and d.access_id=aid and private.f4_delegation_own(d.id)and(p_id is null or d.id=p_id);
 select case when p_id is null then'[]'::jsonb else(select coalesce(jsonb_agg(jsonb_build_object('id',p.id,'revision',p.revision,'payload',p.payload,'payload_sha256',p.payload_sha256,'status',p.status,'message',p.own_message,'current_source',coalesce(private.f4_delegation_current(p),false),'created_at',p.created_at)order by p.revision desc),'[]')from private.partner_profile_proposals p where p.delegation_id=p_id)end into ps;
 return jsonb_build_object('schema_version','besc-delegation-own-v1','lease_id',aid,'delegations',ds,'proposals',ps);
end$$;
create function public.f4_delegation_admin(p_site_id uuid,p_after_time timestamptz default null,p_after_id uuid default null)returns jsonb language plpgsql volatile security definer set search_path=''as $$declare o uuid;ch boolean;ed boolean;ps jsonb;begin
 perform private.f4_read_gate();select organization_id into o from public.publication_sites where id=p_site_id;ch:=private.f1_chair(o);ed:=private.f1_role(o,'publication_editor')and private.f1_role(o,'partner_editor');if not private.f2_account(o)or not(ch or ed)then raise exception'delegation_not_authorized'using errcode='42501';end if;if(p_after_time is null)<>(p_after_id is null)then raise exception'delegation_invalid_input';end if;perform private.f4_limit(p_site_id,'delegation_admin',60);if(select count(*)from public.partners where organization_id=o and deleted_at is null and status='active')>200 then raise exception'delegation_page_required';end if;
 select case when ed then(select coalesce(jsonb_agg(to_jsonb(x)||jsonb_build_object('current_source',coalesce(private.f4_delegation_current(x),false))order by x.created_at,x.id),'[]')from(select p.* from private.partner_profile_proposals p join private.partner_delegations d on d.id=p.delegation_id where d.site_id=p_site_id and p.status<>'draft'and private.f4_delegation_valid(d.id)and private.f1_document_visible(o,d.proof_document_id)and(p_after_time is null or(p.created_at,p.id)>(p_after_time,p_after_id))order by p.created_at,p.id limit 50)x)else'[]'::jsonb end into ps;
 return jsonb_build_object('chair',ch,'curate',ed,'enabled',coalesce((select enabled from private.partner_delegation_settings where site_id=p_site_id),false),'delegations',(select coalesce(jsonb_agg(to_jsonb(d)||jsonb_build_object('valid',private.f4_delegation_valid(d.id))),'[]')from private.partner_delegations d where d.site_id=p_site_id and(ch or private.f1_document_visible(o,d.proof_document_id))),'partners',(select coalesce(jsonb_agg(jsonb_build_object('id',p.id,'name',p.name,'revision',(select coalesce(max(revision),0)from private.partner_publication_revisions where site_id=p_site_id and partner_id=p.id),'roles',case when ed then(select coalesce(jsonb_agg(jsonb_build_object('id',r.id,'role',r.role)),'[]')from public.partner_roles r where r.partner_id=p.id and r.organization_id=o and r.revoked_at is null and r.valid_from<=(clock_timestamp()at time zone'Europe/Brussels')::date and(r.valid_until is null or r.valid_until>=(clock_timestamp()at time zone'Europe/Brussels')::date)and private.f4_partner_document(o,r.proof_document_id)is not null and private.f1_document_visible(o,r.proof_document_id))else'[]'::jsonb end)),'[]')from public.partners p where p.organization_id=o and p.deleted_at is null and p.status='active'),'proposals',ps,'next_after',case when jsonb_array_length(ps)=50 then jsonb_build_object('at',(ps->-1)->>'created_at','id',(ps->-1)->>'id')else null end);
end$$;
-- No account rebinding, renewal or proof restoration revives a previous delegation.
create function private.f4_delegation_revoke_publications()returns trigger language plpgsql security definer set search_path=''as $$begin
 if new.revoked_at is not null and old.revoked_at is null then
  perform private.f1_audit(new.organization_id,new.id,'f4.delegation.revoked');
  update private.partner_publication_entries set withdrawn_at=coalesce(withdrawn_at,clock_timestamp())where selected_revision_id in(select r.id from private.partner_publication_revisions r join private.partner_profile_proposals p on p.id=r.delegated_proposal_id where p.delegation_id=new.id);
  update private.partner_publication_revisions set status='withdrawn'where delegated_proposal_id in(select id from private.partner_profile_proposals where delegation_id=new.id)and status in('submitted','approved');
 end if;return new;
end$$;
create trigger f4_delegation_revoke_publications after update of revoked_at on private.partner_delegations for each row execute function private.f4_delegation_revoke_publications();
create function private.f4_delegation_proposal_withdrawn()returns trigger language plpgsql security definer set search_path=''as $$begin
 if new.status='withdrawn'and old.status is distinct from'withdrawn'then update private.partner_publication_entries set withdrawn_at=coalesce(withdrawn_at,clock_timestamp())where selected_revision_id in(select id from private.partner_publication_revisions where delegated_proposal_id=new.id);update private.partner_publication_revisions set status='withdrawn'where delegated_proposal_id=new.id and status in('submitted','approved');end if;return new;
end$$;
create trigger f4_delegation_proposal_withdrawn after update of status on private.partner_profile_proposals for each row execute function private.f4_delegation_proposal_withdrawn();
create function private.f4_delegation_source_revoked()returns trigger language plpgsql security definer set search_path=''as $$begin
 if tg_table_name='platform_access'then if new.revoked_at is not null then update private.partner_delegations set revoked_at=coalesce(revoked_at,clock_timestamp())where access_id=new.id;end if;
 elsif tg_table_name='document_registry'then if to_jsonb(new)is distinct from to_jsonb(old)then update private.partner_delegations set revoked_at=coalesce(revoked_at,clock_timestamp())where proof_document_id=old.id;end if;
 else update private.partner_delegations set revoked_at=coalesce(revoked_at,clock_timestamp())where person_id=old.id and(old.account_user_id is distinct from new.account_user_id or new.deleted_at is not null);end if;return new;
end$$;
create trigger f4_delegation_access_changed after update of revoked_at on private.platform_access for each row execute function private.f4_delegation_source_revoked();
create trigger f4_delegation_proof_changed after update of url,label,restricted_finance,restricted_governance,media_rights_revoked_at on public.document_registry for each row execute function private.f4_delegation_source_revoked();
create trigger f4_delegation_person_changed after update of account_user_id,deleted_at on public.community_people for each row execute function private.f4_delegation_source_revoked();
create function private.f4_delegation_review_gate()returns trigger language plpgsql security definer set search_path=''as $$begin
 if new.delegated_proposal_id is not null and new.status='approved'and exists(select 1 from private.partner_profile_proposals p where p.id=new.delegated_proposal_id and p.created_by=auth.uid())then raise exception'delegation_independent_review_required'using errcode='42501';end if;return new;
end$$;
create trigger f4_delegation_review_gate before update of status on private.partner_publication_revisions for each row execute function private.f4_delegation_review_gate();
create or replace function private.f4_partner_current(r private.partner_publication_revisions) returns boolean language sql stable security definer set search_path='' as $$
 select private.f4_partner_payload(r.payload) and r.proof_hash=private.f4_partner_evidence(r.organization_id,r.site_id,r.proof_document_id,r.payload->'logo') and r.source_hash=private.f4_partner_source(r.organization_id,r.partner_id,r.role_ids)
 and exists(select 1 from public.partners p where p.id=r.partner_id and p.organization_id=r.organization_id and p.name=r.payload->>'name' and nullif(btrim(p.website),'') is not distinct from r.payload->>'website_url')
 and(select jsonb_agg(role order by role) from public.partner_roles where id=any(r.role_ids))=(select jsonb_agg(v order by v) from jsonb_array_elements_text(r.payload->'roles') v)
 and exists(select 1 from public.document_registry d where d.id=r.proof_document_id and d.organization_id=r.organization_id and d.media_rights_revoked_at is null)
 and private.f4_avatar(r.organization_id,r.site_id,jsonb_build_object('avatar',r.payload->'logo'))
 and(r.delegated_proposal_id is null or exists(select 1 from private.partner_profile_proposals p where p.id=r.delegated_proposal_id and p.status='prepared'and private.f4_delegation_current(p)))
$$;
do $$declare x record;begin for x in select n.nspname,p.proname,pg_get_function_identity_arguments(p.oid)args from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in('public','private')and p.proname like'f4_delegation_%'loop execute format('revoke all on function %I.%I(%s)from public,anon,authenticated,service_role',x.nspname,x.proname,x.args);end loop;end$$;
grant execute on function public.f4_delegation_workflow(uuid,text,jsonb,uuid),public.f4_delegation_me(uuid,uuid),public.f4_delegation_admin(uuid,timestamptz,uuid)to authenticated;
commit;
